#!/usr/bin/env node
/**
 * Generates src/data/authorised.ts from the committed demand map.
 *
 * WHY A GENERATED FILE rather than reading the CSV at render time: the routes
 * must not be able to disagree with the map. If a route linked to a market it
 * decided for itself, we would be back to the v1 lattice — pages generated from
 * an array rather than from evidence — and the keyword-map checker would not
 * catch it, because it only checks pages that EXIST.
 *
 * This is also how the geo tier stops producing dead links: a service hub can
 * only link to the city pages the gate actually authorised. Everything else is
 * named in prose as areaServed coverage.
 */
import fs from 'node:fs';

const rows = fs.readFileSync('../architecture/demand/demand-map.csv', 'utf8')
  .replace(/\r/g, '').trim().split('\n');
const head = rows[0].split(',');
const iUrl = head.indexOf('url');
const iGeo = head.indexOf('geo');
const iSvc = head.indexOf('service');
const iDec = head.indexOf('decision');

const split = (line) => {
  const out = []; let cur = ''; let q = false;
  for (const ch of line) {
    if (ch === '"') q = !q;
    else if (ch === ',' && !q) { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur); return out;
};

const parsed = rows.slice(1).map(split);
const pages = parsed.filter((r) => r[iDec] === 'PAGE');
const cities = [...new Set(pages.filter((r) => !r[iSvc]).map((r) => r[iGeo]))].sort();
const tuples = pages.filter((r) => r[iSvc]).map((r) => [r[iGeo], r[iSvc]]);
const declinedCities = [...new Set(parsed.filter((r) => r[iDec] !== 'PAGE' && !r[iSvc] && r[iUrl].startsWith('/locations/') && r[iUrl].split('/').length === 4).map((r) => r[iGeo]))]
  .filter((g) => !cities.includes(g)).sort();

const byCity = {};
for (const [g, s] of tuples) (byCity[g] ??= []).push(s);
for (const k of Object.keys(byCity)) byCity[k].sort();

const out = `/**
 * AUTO-GENERATED by scripts/gen-authorised.mjs from architecture/demand/demand-map.csv.
 * Do not edit by hand — edit the demand map and regenerate.
 *
 * Keystone v3.2 Part 6A: a page is earned by evidence of demand. These are the
 * geographies and (geo, service) tuples that cleared the two-signal gate. A route
 * may only link to what is in here; everything else is areaServed prose.
 *
 * Generated ${new Date().toISOString().slice(0, 10)} · ${cities.length} city pages · ${tuples.length} city x service pages · ${declinedCities.length} declined cities.
 */
export const AUTHORISED_CITIES: readonly string[] = ${JSON.stringify(cities, null, 2)} as const;

export const AUTHORISED_TUPLES: Readonly<Record<string, readonly string[]>> = ${JSON.stringify(byCity, null, 2)} as const;

/** Declined geographies — named in coverage copy and areaServed, never linked. */
export const DECLINED_CITIES: readonly string[] = ${JSON.stringify(declinedCities, null, 2)} as const;

export const isAuthorisedCity = (geo: string): boolean => AUTHORISED_CITIES.includes(geo);
export const isAuthorisedTuple = (geo: string, service: string): boolean =>
  (AUTHORISED_TUPLES[geo] ?? []).includes(service);
/** Markets that carry this service AND cleared the gate for it. */
export const marketsForService = (service: string): string[] =>
  Object.keys(AUTHORISED_TUPLES).filter((g) => AUTHORISED_TUPLES[g].includes(service)).sort();
`;
fs.writeFileSync('src/data/authorised.ts', out);
console.log(`gen-authorised: ${cities.length} cities, ${tuples.length} tuples, ${declinedCities.length} declined`);
